import hashlib
from pathlib import Path
from urllib.parse import urlparse


class RawCache:
    """Store raw HTML/PDF/Excel files so the crawler can reuse local copies."""

    def __init__(self, root_dir: Path) -> None:
        self.root_dir = root_dir
        self.root_dir.mkdir(parents=True, exist_ok=True)

    def path_for_url(self, url: str, subdir: str, default_suffix: str = ".html") -> Path:
        parsed = urlparse(url)
        suffix = Path(parsed.path).suffix or default_suffix
        if suffix.lower() not in {".html", ".htm", ".pdf", ".xls", ".xlsx", ".csv"}:
            suffix = default_suffix
        digest = hashlib.sha1(url.encode("utf-8")).hexdigest()[:16]
        safe_name = Path(parsed.path).stem or "index"
        safe_name = "".join(ch if ch.isalnum() else "_" for ch in safe_name)[:40]
        directory = self.root_dir / subdir
        directory.mkdir(parents=True, exist_ok=True)
        return directory / f"{safe_name}_{digest}{suffix}"

    @staticmethod
    def has_file(path: Path) -> bool:
        return path.exists() and path.stat().st_size > 0

    @staticmethod
    def write_bytes(path: Path, content: bytes) -> None:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(content)

    @staticmethod
    def read_text(path: Path) -> str:
        return path.read_text(encoding="utf-8", errors="ignore")

import re
from typing import Optional


_FOOTNOTE_PATTERN = re.compile(r"[\s\u3000]*\d+$")
_NON_NUMERIC_PATTERN = re.compile(r"[^0-9.\-]")


def clean_text(value: object) -> str:
    """Normalize whitespace in text extracted from HTML or PDF tables."""
    if value is None:
        return ""
    return re.sub(r"\s+", " ", str(value)).strip()


def clean_disease_name(value: object) -> str:
    """Remove trailing footnote numbers from disease names."""
    text = clean_text(value)
    text = _FOOTNOTE_PATTERN.sub("", text)
    return text.strip()


def parse_int(value: object) -> Optional[int]:
    """Parse an integer from Chinese official table cells."""
    text = clean_text(value).replace(",", "")
    if not text or text in {"-", "—", "--"}:
        return None
    text = _NON_NUMERIC_PATTERN.sub("", text)
    if not text:
        return None
    return int(float(text))


def infer_disease_category(disease_name: str) -> str:
    """Infer disease category from aggregate rows when available."""
    if "甲乙类" in disease_name:
        return "甲乙类合计"
    if "丙类" in disease_name:
        return "丙类合计"
    if "甲乙丙类" in disease_name:
        return "甲乙丙类总计"
    if "其他传染病合计" in disease_name:
        return "重点监测其他传染病合计"
    return ""

from bs4 import BeautifulSoup

from parsers.normalizers import clean_text


def soup_from_html(html: str) -> BeautifulSoup:
    return BeautifulSoup(html, "html.parser")


def extract_page_title(soup: BeautifulSoup) -> str:
    """Return the article title, falling back to the HTML title."""
    title_selectors = [".content h1", ".main h1", "h1"]
    for selector in title_selectors:
        node = soup.select_one(selector)
        if node:
            title = clean_text(node.get_text(" ", strip=True))
            if title:
                return title
    if soup.title:
        return clean_text(soup.title.get_text(" ", strip=True))
    return ""


def extract_tables(soup: BeautifulSoup) -> list[list[list[str]]]:
    """Extract every HTML table as rows of plain text cells."""
    tables: list[list[list[str]]] = []
    for table in soup.find_all("table"):
        rows: list[list[str]] = []
        for tr in table.find_all("tr"):
            cells = [
                clean_text(cell.get_text(" ", strip=True))
                for cell in tr.find_all(["th", "td"])
            ]
            if any(cells):
                rows.append(cells)
        if rows:
            tables.append(rows)
    return tables

